### [P2] (1/2) Add the restore-path guard

**Severity:** `medium`

`Restore-DataFolder` builds destinations from snapshot-relative paths and later hashes and copies them. If a parent directory is already a junction when restore reaches it, path-based `Copy-Item` can write the snapshot outside `$powerToysDataFolder` while appearing successful. This helper rejects a reparse-point root, parent, or existing target; apply it together with (2/2), which invokes it before target access. This addresses a junction that remains present during validation and does not claim to prevent replacement between checking and writing.

```suggestion
function Test-ReparsePoint
{
    param([Parameter(Mandatory)][IO.FileSystemInfo]$Item)

    return ($Item.Attributes -band [IO.FileAttributes]::ReparsePoint) -ne 0
}

function Ensure-DataFolderPath
{
    param([Parameter(Mandatory)][string]$RelativePath)

    $parts = $RelativePath -split '[\\/]'
    if ([IO.Path]::IsPathRooted($RelativePath) -or $parts.Count -eq 0 -or
        @($parts | Where-Object { [string]::IsNullOrWhiteSpace($_) -or $_ -in '.', '..' }).Count -gt 0)
    {
        throw "PowerToys data path '$RelativePath' must be a relative path without traversal components."
    }

    if (-not (Test-Path -LiteralPath $powerToysDataFolder))
    {
        $null = New-Item -ItemType Directory -Force -Path $powerToysDataFolder
    }

    $root = Get-Item -LiteralPath $powerToysDataFolder -Force -ErrorAction Stop
    if (-not $root.PSIsContainer -or (Test-ReparsePoint -Item $root))
    {
        throw "PowerToys data folder '$powerToysDataFolder' must be a directory and cannot be a reparse point."
    }

    $parent = $powerToysDataFolder
    for ($i = 0; $i -lt $parts.Count - 1; $i++)
    {
        $parent = Join-Path $parent $parts[$i]
        if (-not (Test-Path -LiteralPath $parent))
        {
            $null = New-Item -ItemType Directory -Force -Path $parent
        }

        $directory = Get-Item -LiteralPath $parent -Force -ErrorAction Stop
        if (-not $directory.PSIsContainer -or (Test-ReparsePoint -Item $directory))
        {
            throw "PowerToys data path '$parent' must be a directory and cannot be a reparse point."
        }
    }

    $target = Join-Path $powerToysDataFolder $RelativePath
    if (Test-Path -LiteralPath $target)
    {
        $item = Get-Item -LiteralPath $target -Force -ErrorAction Stop
        if (Test-ReparsePoint -Item $item)
        {
            throw "PowerToys data path '$target' cannot be a reparse point."
        }
    }
}

function Save-DataFolder
